CREATE TABLE "category_requests" ("id" TEXT NOT NULL,"scope" TEXT NOT NULL,"parent_category" TEXT,"proposed_name" TEXT NOT NULL,"description" TEXT,"request_reason" TEXT NOT NULL,"source_area" TEXT NOT NULL,"source_draft_id" TEXT,"status" "review_status" NOT NULL DEFAULT 'PENDING',"submitted_by_user_id" TEXT,"reviewed_by_user_id" TEXT,"review_comment" TEXT,"reviewed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "category_requests_pkey" PRIMARY KEY ("id"));
CREATE INDEX "category_requests_status_created_at_idx" ON "category_requests"("status", "created_at");
CREATE TABLE "managed_categories" ("id" TEXT NOT NULL,"scope" TEXT NOT NULL,"parent_name" TEXT,"name" TEXT NOT NULL,"description" TEXT,"is_active" BOOLEAN NOT NULL DEFAULT true,"merged_into_id" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "managed_categories_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "managed_categories_scope_name_key" ON "managed_categories"("scope", "name");
